% ============================================================
% 图表引用文件 - 由 paper-figure 自动生成
% 不要手动编辑，下次运行 paper-figure 时会被覆盖
% ============================================================

% 导入图表包
\usepackage{graphicx}
\usepackage{subcaption}
\usepackage{amsmath}

% 设置图表搜索路径
\graphicspath{{figures/}}

% ---- 数据图引用块 ----
% 格式: \include{fig_图表名}
% 不要手动修改，由 figure 生成脚本自动维护

% 收敛曲线
\newcommand{\figconvergence}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.85\textwidth]{figures/fig_convergence.pdf}
        \caption{算法收敛曲线}
        \label{fig:convergence}
    \end{figure}
}

% 分组柱状图
\newcommand{\figbar}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.9\textwidth]{figures/fig_bar.pdf}
        \caption{方法对比结果}
        \label{fig:bar}
    \end{figure}
}

% 热力图
\newcommand{\figheatmap}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.7\textwidth]{figures/fig_heatmap.pdf}
        \caption{相关系数矩阵}
        \label{fig:heatmap}
    \end{figure}
}

% ROC曲线
\newcommand{\figroc}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.6\textwidth]{figures/fig_roc.pdf}
        \caption{ROC 曲线}
        \label{fig:roc}
    \end{figure}
}

% 混淆矩阵
\newcommand{\figcm}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.6\textwidth]{figures/fig_confusion.pdf}
        \caption{混淆矩阵}
        \label{fig:confusion}
    \end{figure}
}

% Pareto前沿
\newcommand{\figpareto}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.7\textwidth]{figures/fig_pareto.pdf}
        \caption{Pareto 前沿}
        \label{fig:pareto}
    \end{figure}
}

% 雷达图
\newcommand{\figradar}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.6\textwidth]{figures/fig_radar.pdf}
        \caption{多指标雷达图}
        \label{fig:radar}
    \end{figure}
}

% ---- 流程图/架构图引用块 ----
% 由 paper-figure-html 或 paper-figure-drawio 生成

% 技术路线图
\newcommand{\figroadmap}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.95\textwidth]{figures/fig_roadmap.pdf}
        \caption{技术路线图}
        \label{fig:roadmap}
    \end{figure}
}

% 系统架构图
\newcommand{\figarch}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.9\textwidth]{figures/fig_arch.pdf}
        \caption{系统架构图}
        \label{fig:arch}
    \end{figure}
}

% 算法流程图
\newcommand{\figflow}{
    \begin{figure}[H]
        \centering
        \includegraphics[width=0.85\textwidth]{figures/fig_flow.pdf}
        \caption{算法流程图}
        \label{fig:flow}
    \end{figure}
}

% ---- 表格引用块 ----

% 结果汇总表
\newcommand{\tableresult}{
    \begin{table}[H]
        \centering
        \caption{实验结果汇总}
        \label{tab:result}
        \begin{tabular}{lccc}
            \hline
            方法 & 指标1 & 指标2 & 指标3 \\
            \hline
            本文方法 & - & - & - \\
            对比方法 & - & - & - \\
            \hline
        \end{tabular}
    \end{table}
}

% ============================================================
% 图表尺寸预设（由 fig_include_size.py 自动调整）
% ============================================================
\newlength{\figwidthstandard}
\newlength{\figwidthwide}
\newlength{\figwidthfull}
\newlength{\figheightstandard}

\setlength{\figwidthstandard}{0.85\textwidth}
\setlength{\figwidthwide}{0.95\textwidth}
\setlength{\figwidthfull}{\textwidth}
\newlength{\figheightstandard}
\setlength{\figheightstandard}{0.6\textheight}
